package com.example

/**
 * Curated, 100% syllabus-aligned, distinct Flashcards for Commerce & Accounting (ව්‍යාපාර හා ගිණුම්කරණය).
 * Part 2: Categories 11 to 20 (20 distinct questions per category).
 * Strictly guarantees no repeated questions within the same category or across different categories.
 */
object FlashcardBankCommerceSetsPart2 {

  fun getCard(setNum: Int, cardNum: Int, grade: String): CardContentTuple {
    val c = cardNum.coerceIn(1, 20)
    if (grade.contains("11")) {
      return when (setNum) {
        11 -> grade11_set11[(c - 1) % grade11_set11.size]
        12 -> grade11_set12[(c - 1) % grade11_set12.size]
        13 -> grade11_set13[(c - 1) % grade11_set13.size]
        14 -> grade11_set14[(c - 1) % grade11_set14.size]
        15 -> grade11_set15[(c - 1) % grade11_set15.size]
        16 -> grade11_set16[(c - 1) % grade11_set16.size]
        17 -> grade11_set17[(c - 1) % grade11_set17.size]
        18 -> grade11_set18[(c - 1) % grade11_set18.size]
        19 -> grade11_set19[(c - 1) % grade11_set19.size]
        20 -> grade11_set20[(c - 1) % grade11_set20.size]
        else -> grade11_set11[(c - 1) % grade11_set11.size]
      }
    }
    return when (setNum) {
      11 -> set11[(c - 1) % set11.size]
      12 -> set12[(c - 1) % set12.size]
      13 -> set13[(c - 1) % set13.size]
      14 -> set14[(c - 1) % set14.size]
      15 -> set15[(c - 1) % set15.size]
      16 -> set16[(c - 1) % set16.size]
      17 -> set17[(c - 1) % set17.size]
      18 -> set18[(c - 1) % set18.size]
      19 -> set19[(c - 1) % set19.size]
      20 -> set20[(c - 1) % set20.size]
      else -> set11[(c - 1) % set11.size]
    }
  }

  // --- SET 11: මූල්‍ය ප්‍රකාශන (ලාභාලාභ ගිණුම & දළ ලාභය/ශුද්ධ ලාභය) ---
  private val set11 = listOf(
